diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..b1d233f 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -1,17 +1,35 @@
+interface Constraint {
+  text: string;
+  semanticKey?: string;
+}
+
 export interface Record {
   recordId: string;
   path: string;
-  ruledOut: readonly string[];
-  limits: readonly string[];
-  warns: readonly string[];
+  ruledOut: readonly (string | Constraint)[];
+  limits: readonly (string | Constraint)[];
+  warns: readonly (string | Constraint)[];
 }

 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenKeys = new Set<string>();
+
+  const addConstraint = (prefix: string, entry: string | Constraint) => {
+    const constraint = typeof entry === 'string' ? { text: entry } : entry;
+    const key = constraint.semanticKey || constraint.text;
+
+    if (!seenKeys.has(key)) {
+      seenKeys.add(key);
+      lines.push(`- ${prefix}: ${constraint.text}`);
+    }
+  };
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) addConstraint('ruled out', entry);
+    for (const limit of record.limits) addConstraint('limit', limit);
+    for (const warn of record.warns) addConstraint('warn', warn);
   }
+
   return lines.join("\n");
 };
